import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.D7EuCHIT.js";const h=JSON.parse('{"title":"新增播放模式与真实顺序","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/rules.md","filePath":"plugins/rules.md","lastUpdated":1791828780000}'),s={name:"plugins/rules.md"};function l(d,e,i,n,c,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="新增播放模式与真实顺序" tabindex="-1">新增播放模式与真实顺序 <a class="header-anchor" href="#新增播放模式与真实顺序" aria-label="Permalink to &quot;新增播放模式与真实顺序&quot;">​</a></h1><p>使用 <code>examples/rules.c</code>，它发布 LyraPlaybackRulesV3、可选 modes 以及一个“记录导航历史”的可调开关。已有四个模式 ID 0..3 保留；自定义模式用 &gt;=4 的稳定 ID。</p><h2 id="声明模式" tabindex="-1">声明模式 <a class="header-anchor" href="#声明模式" aria-label="Permalink to &quot;声明模式&quot;">​</a></h2><p>modes.describe 输出 size、id 和 UTF-8 label。label 容量 128 字节，模式 ID 不能重复。当前默认菜单最多 64 项且可滚动；这属于默认 UI 容量，插件可替换 UI 实现自己的菜单。</p><p><code>sheet.mode</code> 保存模式 ID，不是菜单行号。卸载提供者时回退实际规则，但不删除用户保存 ID。modes 是 size 检查的可选尾字段，旧表不能无条件读取。</p><h2 id="两个必须一致的函数" tabindex="-1">两个必须一致的函数 <a class="header-anchor" href="#两个必须一致的函数" aria-label="Permalink to &quot;两个必须一致的函数&quot;">​</a></h2><p>next 接收 mode、count、current、delta、automatic 和单调时间熵，返回目录 row 或 -1 停止，以及是否记录历史。order 返回真实队列目录索引和当前队列行。</p><p>只改 next、不改 order，会让播放顺序页显示错误；只改 order、不改 next，会让页面和实际切歌分裂。返回行必须有效，总数不能超过缓冲容量；空目录要安全失败。</p><p>非自定义模式可以委托已查询的默认 rules 接口；不要调用自己的活动接口形成递归。每个模式的手动 previous/next 与自动 EOF 边界应明确定义。</p><h2 id="参数与顺序分离" tabindex="-1">参数与顺序分离 <a class="header-anchor" href="#参数与顺序分离" aria-label="Permalink to &quot;参数与顺序分离&quot;">​</a></h2><p>示例反向列表按每次一首导航，order 按相同反向顺序提供全部歌曲。<code>example.remember_history</code> 只控制返回的 remember 标志，不改变队列顺序，避免参数变化导致 next 与 order 分裂。默认 true；可在配置中改为 false。</p><h2 id="必测场景" tabindex="-1">必测场景 <a class="header-anchor" href="#必测场景" aria-label="Permalink to &quot;必测场景&quot;">​</a></h2><p>空曲库、单首、第一首 previous、最后一首 next、自动 EOF、连续切歌、seek 到末尾、模式切换、目录修改与插件卸载恢复。播放命令不能自动关闭用户正在看的抽屉或歌词页。</p>',13)])])}const m=a(s,[["render",l]]);export{h as __pageData,m as default};
